import { NOT_RECORDED } from './bench-headline.mjs';
import { cpuModel } from '../../documentation/docs/.vitepress/theme/perf-figures.mjs';

// The performance page's recovery tables (docs-performance.mjs writes them between their markers), all from the
// recovery report's headline: a node that loses all its leases at once (`recovery-leases`), a planned hand-over
// (`recovery-handover`), a catch-up under live orders with and without the catch-up bound (`recovery-bound`), and a
// node's first activation on a migrated history (`recovery-first-start`). Each table names its machine and JDK, and
// each row its build. Rows are set side by side, and nothing is computed across them.

export const RECOVERY = {
  report: 'm5max-recovery',
  /** The fix, then its merge base: one batch on one machine, the arms alternating. */
  leases: ['lost-leases.fix', 'lost-leases.base'],
  /** Each batch on one machine: its two MongoDB arms alternating, then one PostgreSQL round. */
  handover: [
    ['handover.mongo.main', 'handover.mongo.fix', 'handover.postgres.fix'],
    ['handover.mongo.6412', 'handover.mongo.patch', 'handover.postgres.patch'],
  ],
  /** Two catch-up permits, then no bound: one run each, dispatched together. */
  bound: ['rehearsal.bound-2', 'rehearsal.bound-0'],
  /** The pairs of the code that ships (#6424) against the parent of #6412, each pair's runs dispatched together. */
  firstStart: ['patch-1', 'patch-2'],
  jobs: ['runner', 'kind'],
};

const WORDS = {
  en: {
    generated:
      "<!-- Generated by .github/scripts/docs-recovery.mjs from the recovery report's headline.json; regenerate with `pnpm docs:reference`. Do not edit. -->",
    arms: {
      fix: 'fix',
      base: 'merge base',
      main: 'main',
      6412: 'main',
      patch: '#6424',
      parent: 'parent of #6412',
    },
    notes: { 6412: 'which carries #6412' },
    probes: 'with log probes',
    unrecorded: image => `${image}, CPU model not recorded`,
    stores: { postgres: 'PostgreSQL', mongo: 'MongoDB' },
    leases: (where, lost, rounds) =>
      `${where}, MongoDB, one node. The fix against its merge base, one batch, ${rounds} rounds a side alternating. In every round the node lost all ${lost} of its leases; each time runs from a partition's loss to its acquisition.`,
    leasesHead: "| Build | First back | Last back | Back at each round's end |",
    notAllBack: 'not all back',
    of: (counts, lost) => `${counts} of ${lost}`,
    handover: (where, nodes, sent) =>
      `${where}, ${nodes} nodes, CI's E3 hand-over step. Each round sent ${sent} commands; a failed one is a saga's timed-out wait. Each batch alternated its two MongoDB arms, then ran one PostgreSQL round.`,
    batch: n => `**Batch ${n}:**`,
    handoverHead:
      '| Build | Store | Failed waits per round | p99, lowest to highest round |',
    bound: (where, fix, runs) =>
      `${where}, the migration rehearsal's live orders on the V10 host's first start on an imported log, at #6412's head \`${fix}\` plus the rehearsal's instrumentation. Each arm is a run of its own (${runs}), the two dispatched together on separate runners, so their rows stand apart.`,
    permits: n => (n === 0 ? 'no bound' : `${n} permits`),
    firstStart: where =>
      `${where}, the same live orders at the default bound. Each arm is its code plus the rehearsal's instrumentation; a pair's runs were dispatched together, so they share a window, not a runner.`,
    pair: (n, runs) => `**Pair ${n}**, runs ${runs}:`,
    liveHead: (lead, sent) =>
      `| ${lead} | Job | Failed of ${sent} | Worst second's p99 | Catch-up |`,
    lead: { bound: 'Catch-up permits', firstStart: 'Build' },
    where: (cpu, jdk) => `${cpu}, JDK ${jdk}`,
    list: ', ',
    separator: ', ',
    and: ' and ',
  },
  zh: {
    generated:
      '<!-- 由 .github/scripts/docs-recovery.mjs 依据恢复报告的 headline.json 生成；用 `pnpm docs:reference` 重新生成。请勿手改。 -->',
    arms: {
      fix: '修复',
      base: '合并基点',
      main: 'main',
      6412: 'main',
      patch: '#6424',
      parent: '#6412 的父提交',
    },
    notes: { 6412: '含 #6412' },
    probes: '带日志探针',
    unrecorded: image => `${image}，未记录 CPU 型号`,
    stores: { postgres: 'PostgreSQL', mongo: 'MongoDB' },
    leases: (where, lost, rounds) =>
      `${where}，MongoDB，一个节点。修复对比其合并基点，同一批测量，每侧 ${rounds} 轮交替。每一轮节点都失去了全部 ${lost} 个租约；每个时间从一个分区失去租约起，到它重新获得为止。`,
    leasesHead: '| 构建 | 第一个恢复 | 最后一个恢复 | 每轮结束时已恢复 |',
    notAllBack: '未全部恢复',
    of: (counts, lost) => `${counts}（共 ${lost}）`,
    handover: (where, nodes, sent) =>
      `${where}，${nodes} 个节点，CI 的 E3 交接步骤。每轮发送 ${sent} 条命令；失败的一条是 saga 的一次等待超时。每批测量先交替运行两个 MongoDB 分支，再跑一轮 PostgreSQL。`,
    batch: n => `**第 ${n} 批：**`,
    handoverHead: '| 构建 | 存储 | 每轮失败的等待 | p99，最低到最高的一轮 |',
    bound: (where, fix, runs) =>
      `${where}，迁移演练中 V10 主机在导入的日志上首次启动时的实时订单，构建为 #6412 的头 \`${fix}\` 加上演练的埋点。每个分支是一次单独的运行（${runs}），两者同时派发、在不同的 runner 上运行，所以各行各自成立。`,
    permits: n => (n === 0 ? '不设上限' : `${n} 个许可`),
    firstStart: where =>
      `${where}，同样的实时订单，使用默认上限。每个分支是它的代码加上演练的埋点；一对中的两次运行同时派发，所以它们处于同一时段，但不在同一台 runner 上。`,
    pair: (n, runs) => `**第 ${n} 对**，运行 ${runs}：`,
    liveHead: (lead, sent) =>
      `| ${lead} | 任务 | 失败（共 ${sent}） | 最差一秒的 p99 | 追赶 |`,
    lead: { bound: '追赶许可', firstStart: '构建' },
    where: (cpu, jdk) => `${cpu}，JDK ${jdk}`,
    list: '、',
    separator: '，',
    and: ' 与 ',
  },
};

const number = value =>
  value.toLocaleString('en-US', { maximumFractionDigits: 1 });

/** A duration in seconds as the page prints it: `2.4 s`. */
export const seconds = value => `${number(value)} s`;

const ms = value => `${number(value)} ms`;

/** A `[lowest, highest]` pair as one value when both are the same, else as `lowest–highest`. */
export const span = ([low, high], unit) =>
  low === high ? unit(low) : `${unit(low).split(' ')[0]}–${unit(high)}`;

const row = cells =>
  `| ${cells.map(text => String(text).replaceAll('|', '\\|')).join(' | ')} |`;

const align = (left, right) =>
  `| ${[...Array(left).fill('---'), ...Array(right).fill('---:')].join(' | ')} |`;

/** The one value all `values` share, or a failure naming what differs. */
const same = (values, what) => {
  const distinct = [...new Set(values.map(String))];
  if (distinct.length !== 1)
    throw new Error(
      `${RECOVERY.report}: the rows of one table differ in ${what} (${distinct.join(', ')})`,
    );
  return values[0];
};

/** The recovery headline's figures by id, refusing a missing headline or figure. */
const figuresOf = (headlines, ids) => {
  const headline = headlines.find(h => h.report === RECOVERY.report);
  if (!headline)
    throw new Error(`the recovery blocks need the ${RECOVERY.report} headline`);
  return ids.map(id => {
    const figure = headline.figures.find(f => f.id === id);
    if (!figure) throw new Error(`${RECOVERY.report} has no figure ${id}`);
    return figure;
  });
};

/** A CPU as a reader names it (cpuModel), or the runner image whose CPU model the run did not record. */
const cpuText = (words, cpu) => {
  const image = cpu.match(new RegExp(`^(.*), CPU model ${NOT_RECORDED}$`));
  return image ? words.unrecorded(image[1]) : cpuModel(cpu);
};

/** Where the figures ran, said once for a table: their CPU and their JDK, which every row must share. */
const whereOf = (words, figures) =>
  words.where(
    cpuText(
      words,
      same(
        figures.map(f => f.cpu),
        'CPU',
      ),
    ),
    same(
      figures.map(f => f.jdk),
      'JDK',
    ),
  );

/** A row's build: its arm as the report names it, its commit, what it carries, and whether its tree had log probes. */
const build = (words, arm, figure) =>
  [
    `${words.arms[arm]} \`${figure.commit}\``,
    ...(words.notes[arm] ? [words.notes[arm]] : []),
    ...(figure.changed ? [words.probes] : []),
  ].join(words.separator);

const armOf = id => id.split('.').at(-1);

export function leasesBlock(locale, headlines) {
  const words = WORDS[locale];
  const figures = figuresOf(headlines, RECOVERY.leases);
  const lost = same(
    figures.map(f => f.lost),
    'leases lost',
  );
  return [
    words.generated,
    '',
    words.leases(
      whereOf(words, figures),
      lost,
      same(
        figures.map(f => f.rounds),
        'rounds',
      ),
    ),
    '',
    words.leasesHead,
    align(1, 3),
    ...figures.map(f =>
      row([
        build(words, armOf(f.id), f),
        span(f.firstBackSeconds, seconds),
        f.lastBackSeconds ? span(f.lastBackSeconds, seconds) : words.notAllBack,
        words.of(f.backAtEnd.join(words.list), lost),
      ]),
    ),
  ].join('\n');
}

export function handoverBlock(locale, headlines) {
  const words = WORDS[locale];
  const batches = RECOVERY.handover.map(ids => figuresOf(headlines, ids));
  const all = batches.flat();
  return [
    words.generated,
    '',
    words.handover(
      whereOf(words, all),
      same(
        all.map(f => f.nodes),
        'nodes',
      ),
      number(
        same(
          all.flatMap(f => f.sent),
          'commands sent a round',
        ),
      ),
    ),
    ...batches.flatMap((figures, i) => [
      '',
      words.batch(i + 1),
      '',
      words.handoverHead,
      align(2, 2),
      ...figures.map(f =>
        row([
          build(words, armOf(f.id), f),
          words.stores[f.store],
          f.failedWaits.join(words.list),
          span(f.p99Ms, ms),
        ]),
      ),
    ]),
  ].join('\n');
}

/** A table of live orders, a row a job of each arm: its lead cell, then failed, worst second and catch-up. */
const liveTable = (words, lead, arms) => {
  const rows = arms.flatMap(({ cell, figures }) =>
    figures.map(f => ({ cell, f })),
  );
  return [
    words.liveHead(
      words.lead[lead],
      number(
        same(
          rows.map(({ f }) => f.sent),
          'live orders sent',
        ),
      ),
    ),
    align(2, 3),
    ...rows.map(({ cell, f }) =>
      row([
        cell,
        f.job,
        number(f.failed),
        ms(f.worstSecondP99Ms),
        seconds(f.catchUpSeconds),
      ]),
    ),
  ];
};

export function boundBlock(locale, headlines) {
  const words = WORDS[locale];
  const arms = RECOVERY.bound.map(arm =>
    figuresOf(
      headlines,
      RECOVERY.jobs.map(job => `${arm}.${job}`),
    ),
  );
  const all = arms.flat();
  return [
    words.generated,
    '',
    words.bound(
      whereOf(words, all),
      same(
        all.map(f => f.fix),
        'fix',
      ),
      arms.map(figures => figures[0].run).join(words.and),
    ),
    '',
    ...liveTable(
      words,
      'bound',
      arms.map(figures => ({
        cell: `${words.permits(figures[0].maxCatchUps)}${words.separator}\`${figures[0].commit}\``,
        figures,
      })),
    ),
  ].join('\n');
}

export function firstStartBlock(locale, headlines) {
  const words = WORDS[locale];
  const headline = headlines.find(h => h.report === RECOVERY.report);
  const pairs = RECOVERY.firstStart.map(pair => {
    const arms = [
      ...new Set(
        (headline?.figures ?? [])
          .filter(f => f.kind === 'first-start' && f.pair === pair)
          .map(f => f.arm),
      ),
    ].sort((a, b) => (a === 'parent' ? -1 : b === 'parent' ? 1 : 0));
    if (arms.length !== 2)
      throw new Error(
        `${RECOVERY.report}: first-start pair ${pair} has ${arms.length} arms, not 2`,
      );
    return arms.map(arm =>
      figuresOf(
        headlines,
        RECOVERY.jobs.map(job => `first-start.${pair}.${arm}.${job}`),
      ),
    );
  });
  return [
    words.generated,
    '',
    words.firstStart(whereOf(words, pairs.flat(2))),
    ...pairs.flatMap((arms, i) => [
      '',
      words.pair(i + 1, arms.map(figures => figures[0].run).join(words.and)),
      '',
      // A job's two arms side by side: the runner's rows, then kind's.
      ...liveTable(
        words,
        'firstStart',
        RECOVERY.jobs
          .map((_, j) => arms.map(figures => figures[j]))
          .flatMap(jobFigures =>
            jobFigures.map(f => ({
              cell: build(words, f.arm, f),
              figures: [f],
            })),
          ),
      ),
    ]),
  ].join('\n');
}
